function setLang(lang){
  if(!T[lang])return;
  localStorage.setItem('storehub_lang',lang);
  document.documentElement.lang=lang;
  var info=LANGUAGES.find(function(l){return l.code===lang;});
  if(info&&info.rtl){document.documentElement.dir='rtl';}else{document.documentElement.dir='ltr';}
  applyTranslations();
  updateLangUI();
}
function t(key){var lang=localStorage.getItem('storehub_lang')||'en';return(T[lang]&&T[lang][key])||(T.en[key])||key;}
function applyTranslations(){
  var lang=localStorage.getItem('storehub_lang')||'en';
  var dict=T[lang]||T.en;
  document.querySelectorAll('[data-i18n]').forEach(function(el){
    var k=el.getAttribute('data-i18n');
    if(dict[k]!==undefined){
      var txt=dict[k];
      var vars=['name','number','amount','profit','stock','errorDetail'];
      vars.forEach(function(v){
        var attr=el.getAttribute('data-flash-'+v.replace(/([A-Z])/g,'-$1').toLowerCase());
        if(attr){txt=txt.replace('{'+v+'}',attr);}
      });
      el.textContent=txt;
    }
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el){
    var k=el.getAttribute('data-i18n-placeholder');
    if(dict[k]!==undefined){el.placeholder=dict[k];}
  });
  var info=LANGUAGES.find(function(l){return l.code===lang;});
  if(info&&info.rtl){document.documentElement.dir='rtl';}else{document.documentElement.dir='ltr';}
}
function updateLangUI(){
  var lang=localStorage.getItem('storehub_lang')||'en';
  var info=LANGUAGES.find(function(l){return l.code===lang;});
  var btn=document.getElementById('currentLangBtn');
  var dd=document.getElementById('langDropdown');
  if(btn){
    var flagStr='';
    try{flagStr=eval('"'+info.flag+'"');}catch(e){flagStr='';}
    btn.innerHTML='<span class="lang-flag">'+flagStr+'</span> <span class="lang-name">'+info.name+'</span> <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="6 9 12 15 18 9"></polyline></svg>';
  }
  if(dd){
    dd.querySelectorAll('.lang-option').forEach(function(opt){
      opt.classList.toggle('active',opt.dataset.lang===lang);
    });
  }
}
function buildLangDropdown(){
  var dd=document.getElementById('langDropdown');
  if(!dd)return;
  dd.innerHTML='';
  LANGUAGES.forEach(function(lang){
    var opt=document.createElement('div');
    opt.className='lang-option'+(lang.code===(localStorage.getItem('storehub_lang')||'en')?' active':'');
    opt.dataset.lang=lang.code;
    var flagStr='';
    try{flagStr=eval('"'+lang.flag+'"');}catch(e){flagStr='';}
    opt.innerHTML='<span class="lang-flag">'+flagStr+'</span><span class="lang-name">'+lang.name+'</span>';
    opt.addEventListener('click',function(){setLang(lang.code);});
    dd.appendChild(opt);
  });
  var current=localStorage.getItem('storehub_lang')||'en';
  var currentLang=LANGUAGES.find(function(l){return l.code===current;})||LANGUAGES[0];
  var autoScroll=(currentLang.code!=='en');
  if(autoScroll){
    setTimeout(function(){
      var active=dd.querySelector('.lang-option.active');
      if(active){active.scrollIntoView({block:'center'});}
    },100);
  }
}
