function applyKeyAliases(){
  Object.keys(T).forEach(function(lang){
    Object.keys(KEY_ALIASES).forEach(function(alias){
      if(!T[lang][alias]&&T[lang][KEY_ALIASES[alias]]){T[lang][alias]=T[lang][KEY_ALIASES[alias]];}
    });
  });
}
