function addNewKeys(){
  Object.keys(NEW_KEYS).forEach(function(lang){
    if(!T[lang])return;
    Object.keys(NEW_KEYS[lang]).forEach(function(k){
      if(!T[lang][k])T[lang][k]=NEW_KEYS[lang][k];
    });
  });
}
addNewKeys();

document.addEventListener('DOMContentLoaded',function(){
  var saved=localStorage.getItem('storehub_lang');
  if(!saved){localStorage.setItem('storehub_lang','en');saved='en';}
  applyTranslations();
  updateLangUI();
  buildLangDropdown();
  document.addEventListener('click',function(e){
    var btn=document.getElementById('currentLangBtn');
    var dd=document.getElementById('langDropdown');
    if(btn&&dd&&!btn.contains(e.target)&&!dd.contains(e.target)){
      dd.classList.remove('show');
      btn.classList.remove('active');
    }
  });
});

